var minArrayLength = function(nums, k) {
    let ans = 1;
    let y = BigInt(nums[0]);
    const bk = BigInt(k);
    for (let i = 1; i < nums.length; i++) {
        const x = BigInt(nums[i]);
        if (x === 0n) return 1;
        if (x * y <= bk) {
            y *= x;
        } else {
            y = x;
            ans++;
        }
    }
    return ans;
};
